import{_ as a,o as t,c as r,ak as n}from"./chunks/framework.B8jO0odJ.js";const f=JSON.parse('{"title":"Chainy offline records and later teacher services","description":"October 23, 2026. Christian owns storage; Sean authors evidence procedures; Sherwin coordinates arrangements; Miguel owns screens. GDD v2 separates gameplay from later service","frontmatter":{"title":"Chainy offline records and later teacher services","description":"October 23, 2026. Christian owns storage; Sean authors evidence procedures; Sherwin coordinates arrangements; Miguel owns screens. GDD v2 separates gameplay from later service","source":"docs/offline-data-plan.md","category":"Research & evaluation","sourceUpdated":"2026-10-23T16:51:22+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/offline-data-plan.md","filePath":"content/docs/offline-data-plan.md"}'),o={name:"content/docs/offline-data-plan.md"};function i(s,e,d,c,l,p){return t(),r("div",null,[...e[0]||(e[0]=[n('<div><h1 id="chainy-offline-records-and-later-teacher-services">Chainy offline records and later teacher services<a class="header-anchor" href="#chainy-offline-records-and-later-teacher-services" aria-label="Link to this section">​</a></h1><p>October 23, 2026. Christian owns storage; Sean authors evidence procedures; Sherwin coordinates arrangements; Miguel owns screens. <a href="/Chainy-Docs/content/docs/game-design.html">GDD v2</a> separates gameplay from later services.</p><h2 id="november-10-core">November 10 core<a class="header-anchor" href="#november-10-core" aria-label="Link to this section">​</a></h2><p>Play and save entirely on the device using a clearly labeled local demo profile. SQLite persists quests, journal/encyclopedia progress, inventory, balances, ledger, world restoration, checkpoints and versions. A reward or purchase commits related changes together and can be retried without duplication. A code is not authentication or cross-device recovery.</p><p>Cryptita Plays community beta testing needs a safe, approved observation/evidence process, not an unfinished teacher platform. Sean confirms necessary fields, permitted participants, custodian and restricted destination. A minimal staff export may be used only if needed and tested; do not make a broad collection service block the gameplay core.</p><h2 id="separate-jobs">Separate jobs<a class="header-anchor" href="#separate-jobs" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Job</th><th>Boundary</th></tr></thead><tbody><tr><td>Offline play/save</td><td>Local SQLite; independent of a nearby teacher after later enrollment</td></tr><tr><td>Enrollment</td><td>Full-product Teacher/Student selection, developer-issued teacher voucher/one online activation, offline student pairing and protected dashboard; later service, not working beta security</td></tr><tr><td>Collection</td><td>Gather approved logical records from personal learner phones; 20–40 phones is a design use case, not proven simultaneous connectivity</td></tr><tr><td>Upload/transfer</td><td>Separately confirm receipt at the approved restricted destination; SQLite does not synchronize itself</td></tr><tr><td>Content update</td><td>Versioned content package; define compatibility and interruption behavior</td></tr><tr><td>App update</td><td>Signed APK with tested in-place data preservation; not a content update or silent-install promise</td></tr></tbody></table><p>Nearby Connections/local Wi-Fi are prototype candidates, not selected or implemented solutions. Do not expose developer credentials, real wallet secrets or identity maps. Game blockchain nodes are simulated records, not learner phones acting as a real blockchain.</p><h2 id="data-handling-and-recovery">Data handling and recovery<a class="header-anchor" href="#data-handling-and-recovery" aria-label="Link to this section">​</a></h2><ul><li>Collect only approved fields; community feedback is not automatically school-approved research.</li><li>Keep identity mapping with the authorized custodian; no participant records or identifiable photos in repositories/issues.</li><li>Define whether evidence means current progress, a playthrough, an answer or a first independent AI test; do not count replay as new independent learning evidence.</li><li>Cancelled/failed export preserves local records. Receipt confirmation is separate from file creation.</li><li>Repeat collection must not inflate totals. Keep profiles separated.</li><li>Test backups, version changes, interrupted saves and in-place updates with synthetic records.</li><li>Never delete local data merely because export was attempted.</li></ul><p>See the <a href="/Chainy-Docs/content/docs/design/database-schema.html">database contract</a>, <a href="/Chainy-Docs/content/docs/qa-evaluation.html">evaluation plan</a> and <a href="/Chainy-Docs/content/docs/kanban-plan-draft.html">November 10 schedule</a>.</p></div>',1)])])}const m=a(o,[["render",i]]);export{f as __pageData,m as default};
